using System;
using System.Collections.Generic;
using System.IO;
using NUnit.Framework;
using UnityEngine;

namespace MotionBricks.Tests
{
    /// <summary>
    /// Compares the C# port against fixtures generated by the reference Python engine
    /// (<c>tools/unity_golden/export_golden.py</c>). The fixtures hold the packed input tensors of two
    /// chained generations, the raw ONNX outputs, and the final corrected frames.
    /// </summary>
    public sealed class GoldenParityTests
    {
        private SomaSkeleton _skeleton;

        [SetUp]
        public void SetUp()
        {
            _skeleton = SomaSkeleton.CreateDefault();
        }

        private static string PackagePath => FindPackagePath();

        private static string FindPackagePath()
        {
            // The package's own folder, found through the Unity package manager.
            var packageInfo = UnityEditor.PackageManager.PackageInfo.FindForAssembly(typeof(GoldenParityTests).Assembly);
            if (packageInfo != null)
            {
                var candidate = Path.Combine(packageInfo.resolvedPath, "Tests", "Fixtures");
                if (Directory.Exists(candidate))
                {
                    return candidate;
                }
            }

            // Fall back to the repository layout used during development.
            var assemblyPath = typeof(GoldenParityTests).Assembly.Location;
            var directory = new DirectoryInfo(assemblyPath);
            while (directory != null)
            {
                var candidate = Path.Combine(directory.FullName, "Tests", "Fixtures");
                if (Directory.Exists(candidate))
                {
                    return candidate;
                }

                directory = directory.Parent;
            }

            var repoRoot = Directory.GetParent(Application.dataPath)?.Parent?.Parent?.Parent?.FullName;
            return repoRoot == null ? null : Path.Combine(repoRoot, "unity", "com.nvlabs.motionbricks", "Tests", "Fixtures");
        }

        private Dictionary<string, object> LoadGolden()
        {
            var path = Path.Combine(PackagePath, "golden_soma.json");
            Assert.IsTrue(File.Exists(path), $"The golden fixture is missing: {path}");
            var root = MiniJson.Parse(File.ReadAllText(path)).ReadValue().AsObject();
            return root;
        }

        /// <summary>The skeleton of the fixture matches the bundled SOMA skeleton.</summary>
        [Test]
        public void SkeletonMatchesFixture()
        {
            var golden = LoadGolden();
            Assert.AreEqual(
                (int)golden["skeleton_joint_count"].AsNumber(),
                _skeleton.NumJoints);

            var modelJoints = golden["model_joint_names"].AsArray();
            Assert.AreEqual(SomaModelContract.JointNames.Length, modelJoints.Count);
            for (var index = 0; index < modelJoints.Count; index++)
            {
                Assert.AreEqual(SomaModelContract.JointNames[index], modelJoints[index].AsString());
            }
        }

        /// <summary>
        /// The packed input tensors of the C# encoder match the reference engine's tensors.
        /// </summary>
        [Test]
        public void EncodeMatchesReference()
        {
            var golden = LoadGolden();
            foreach (var generation in golden["generations"].AsArray())
            {
                var doc = generation.AsObject();
                var context = ReadPoses(doc["context_poses"]);
                var target = ReadPoses(doc["target_poses"]);

                var generator = new SomaGenerator(new RecordingBackend(), _skeleton);
                var contextToken = new SomaPoseToken(_skeleton);
                var targetToken = new SomaPoseToken(_skeleton);
                contextToken.UpdateFromPoses(context, _skeleton.NumJoints, MbContract.PosesPerToken);
                targetToken.UpdateFromPoses(target, _skeleton.NumJoints, MbContract.PosesPerToken);

                var config = new MotionBricksInferenceConfig();
                generator.EncodeForTest(contextToken, targetToken, config);

                var packed = doc["packed"].AsObject();
                AssertArrayClose(
                packed["global_root_values"].AsFlatFloatArray(),
                generator.LastInputs.GlobalRootValues,
                2e-4f,
                $"{doc["name"]} global_root_values");
                AssertArrayClose(
                    packed["local_root_values"].AsFlatFloatArray(),
                    generator.LastInputs.LocalRootValues,
                    2e-4f,
                    $"{doc["name"]} local_root_values");
                AssertArrayClose(
                    packed["local_poses"].AsFlatFloatArray(),
                    generator.LastInputs.LocalPoses,
                    2e-4f,
                    $"{doc["name"]} local_poses");
                AssertArrayClose(
                    packed["has_global_root_values"].AsIntArray(),
                    generator.LastInputs.HasGlobalRootValues,
                    0f,
                    $"{doc["name"]} has_global_root_values");
                AssertArrayClose(
                    packed["has_local_root_values"].AsIntArray(),
                    generator.LastInputs.HasLocalRootValues,
                    0f,
                    $"{doc["name"]} has_local_root_values");
                AssertArrayClose(
                    packed["has_local_poses"].AsIntArray(),
                    generator.LastInputs.HasLocalPoses,
                    0f,
                    $"{doc["name"]} has_local_poses");
                AssertArrayClose(
                    packed["allowed_pred_num_tokens"].AsIntArray(),
                    generator.LastInputs.AllowedPredNumTokens,
                    0f,
                    $"{doc["name"]} allowed_pred_num_tokens");
            }
        }

        /// <summary>
        /// The decoded and endpoint-corrected frames match the reference engine's frames.
        /// </summary>
        [Test]
        public void DecodeMatchesReference()
        {
            var golden = LoadGolden();
            foreach (var generation in golden["generations"].AsArray())
            {
                var doc = generation.AsObject();
                var context = ReadPoses(doc["context_poses"]);
                var target = ReadPoses(doc["target_poses"]);

                var backend = new RecordingBackend();
                var generator = new SomaGenerator(backend, _skeleton);
                var contextToken = new SomaPoseToken(_skeleton);
                var targetToken = new SomaPoseToken(_skeleton);
                contextToken.UpdateFromPoses(context, _skeleton.NumJoints, MbContract.PosesPerToken);
                targetToken.UpdateFromPoses(target, _skeleton.NumJoints, MbContract.PosesPerToken);

                // Feed the reference ONNX output into the port.
                backend.PredGlobalMotions = doc["pred_global_motions"].AsFlatFloatArray();
                backend.PredNumTokens = new[] { (int)doc["pred_num_tokens"].AsNumber() };

                var output = new SomaAnimationBuffer(_skeleton);
                generator.Generate(contextToken, targetToken, output, new MotionBricksInferenceConfig());

                var generationName = doc["name"].AsString();
                Assert.AreEqual((int)doc["num_frames"].AsNumber(), output.NumFrames, generationName);

                var expectedFrames = doc["frames"].AsArray();
                var expectedContacts = doc["foot_contacts"].AsArray();
                var worstPosition = 0f;
                var worstRotation = 0f;

                for (var frame = 0; frame < output.NumFrames; frame++)
                {
                    for (var joint = 0; joint < _skeleton.NumJoints; joint++)
                    {
                        var expected = expectedFrames[frame].AsArray()[joint].AsPose();
                        var actual = output.Poses[frame * _skeleton.NumJoints + joint];
                        worstPosition = Mathf.Max(worstPosition, (expected.position - actual.position).magnitude);
                        worstRotation = Mathf.Max(
                            worstRotation,
                            RotationError(expected.rotation, actual.rotation));
                    }
                }

                for (var frame = 0; frame < output.NumFrames; frame++)
                {
                    var expectedRow = expectedContacts[frame].AsArray();
                    for (var contact = 0; contact < MbContract.FootContactCount; contact++)
                    {
                        var expected = (float)expectedRow[contact].AsNumber();
                        var actual = output.FootContacts[frame * MbContract.FootContactCount + contact];
                        Assert.AreEqual(expected, actual, 1e-4f, $"{generationName} foot contact");
                    }
                }

                Assert.Less(worstPosition, 5e-3f, $"{doc["name"]} joint positions differ by {worstPosition} m");
                Assert.Less(worstRotation, 5e-3f, $"{doc["name"]} joint rotations differ by {worstRotation} rad");
            }
        }

        /// <summary>The BVH loader and clip sampler match the reference clip samples.</summary>
        [Test]
        public void BvhLoaderMatchesReference()
        {
            var path = Path.Combine(PackagePath, "bvh_samples.json");
            Assert.IsTrue(File.Exists(path), $"The BVH fixture is missing: {path}");
            var root = MiniJson.Parse(File.ReadAllText(path)).ReadValue().AsObject();

            var clip = SomaBvhLoader.LoadBvh(Path.Combine(PackagePath, "mini_walk.mbvh"), _skeleton);
            Assert.AreEqual((int)root["bvh_frames"].AsNumber(), clip.NumFrames);
            Assert.AreEqual((float)root["bvh_sample_rate"].AsNumber(), clip.SampleRate, 1e-3f);

            var offsets = root["root_offsets"].AsArray();
            var samples = root["samples"].AsArray();
            var destination = new Pose[_skeleton.NumJoints];

            foreach (var sample in samples)
            {
                var doc = sample.AsObject();
                var time = (float)doc["time"].AsNumber();
                var offsetIndex = (int)doc["root_offset"].AsNumber();
                var offsetValues = offsets[offsetIndex].AsFloatArray();
                var offset = new Pose(
                    new Vector3(offsetValues[0], offsetValues[1], offsetValues[2]),
                    new Quaternion(offsetValues[3], offsetValues[4], offsetValues[5], offsetValues[6]));

                clip.Sample(time, destination, offset);

                var expected = doc["pose"].AsArray();
                var worstPosition = 0f;
                var worstRotation = 0f;
                for (var joint = 0; joint < _skeleton.NumJoints; joint++)
                {
                    var expectedPose = expected[joint].AsPose();
                    worstPosition = Mathf.Max(worstPosition, (expectedPose.position - destination[joint].position).magnitude);
                        worstRotation = Mathf.Max(
                            worstRotation,
                            RotationError(expectedPose.rotation, destination[joint].rotation));
                }

                Assert.Less(worstPosition, 1e-3f, $"joint positions differ by {worstPosition} m");
                Assert.Less(worstRotation, 2e-3f, $"joint rotations differ by {worstRotation} rad");
            }
        }

        /// <summary>The IK corrector matches the reference two-bone IK at every weight.</summary>
        [Test]
        public void IkCorrectorMatchesReference()
        {
            var path = Path.Combine(PackagePath, "golden_ik.json");
            Assert.IsTrue(File.Exists(path), $"The IK fixture is missing: {path}");
            var root = MiniJson.Parse(File.ReadAllText(path)).ReadValue().AsObject();

            var corrector = new TargetPoseIkCorrector(
                _skeleton, TargetPoseIkCorrector.CreateSomaIkRig(_skeleton));

            var played = ReadSinglePose(root["played_pose"]);
            var target = ReadSinglePose(root["target_pose"]);
            corrector.CapturePins(target, (MbTwoBoneIk.IkPin)(int)root["pin_mask"].AsNumber());

            foreach (var result in root["results"].AsArray())
            {
                var doc = result.AsObject();
                var expected = doc["pose"].AsArray();
                var weight = (float)doc["weight"].AsNumber();

                var actual = new Pose[_skeleton.NumJoints];
                Array.Copy(played, actual, played.Length);
                corrector.Apply(actual, weight);

                var worstPosition = 0f;
                var worstRotation = 0f;
                for (var joint = 0; joint < _skeleton.NumJoints; joint++)
                {
                    var expectedPose = expected[joint].AsPose();
                    worstPosition = Mathf.Max(worstPosition, (expectedPose.position - actual[joint].position).magnitude);
                        worstRotation = Mathf.Max(
                            worstRotation,
                            RotationError(expectedPose.rotation, actual[joint].rotation));
                }

                Assert.Less(worstPosition, 1e-3f, $"weight {weight}: joint positions differ by {worstPosition} m");
                Assert.Less(worstRotation, 2e-3f, $"weight {weight}: joint rotations differ by {worstRotation} rad");
            }
        }

        /// <summary>
        /// Returns the angle between two rotations in radians. Both quaternions are normalized first,
        /// because fixture rounding leaves them a little off unit length and Quaternion.Angle assumes
        /// normalized inputs.
        /// </summary>
        private static float RotationError(Quaternion expected, Quaternion actual)
        {
            var e = MbPose.Normalize(expected);
            var a = MbPose.Normalize(actual);
            return Quaternion.Angle(e, a) * Mathf.Deg2Rad;
        }

        private Pose[] ReadSinglePose(object value)
        {
            var joints = value.AsArray();
            var result = new Pose[_skeleton.NumJoints];
            for (var joint = 0; joint < _skeleton.NumJoints; joint++)
            {
                result[joint] = joints[joint].AsPose();
            }

            return result;
        }

        private Pose[] ReadPoses(object value)
        {
            var poses = value.AsArray();
            var result = new Pose[poses.Count * _skeleton.NumJoints];
            for (var pose = 0; pose < poses.Count; pose++)
            {
                var joints = poses[pose].AsArray();
                for (var joint = 0; joint < _skeleton.NumJoints; joint++)
                {
                    result[pose * _skeleton.NumJoints + joint] = joints[joint].AsPose();
                }
            }

            return result;
        }

        private static void AssertArrayClose(float[] expected, float[] actual, float tolerance, string message)
        {
            Assert.AreEqual(expected.Length, actual.Length, $"{message}: length");
            for (var index = 0; index < expected.Length; index++)
            {
                Assert.AreEqual(expected[index], actual[index], tolerance, $"{message} at {index}");
            }
        }

        private static void AssertArrayClose(int[] expected, int[] actual, float tolerance, string message)
        {
            Assert.AreEqual(expected.Length, actual.Length, $"{message}: length");
            for (var index = 0; index < expected.Length; index++)
            {
                Assert.AreEqual(expected[index], actual[index], tolerance, $"{message} at {index}");
            }
        }

        /// <summary>A backend that returns a prepared prediction instead of running the model.</summary>
        private sealed class RecordingBackend : ISomaInferenceBackend
        {
            public string ExecutionProvider => "recording";

            public float[] PredGlobalMotions { get; set; }

            public int[] PredNumTokens { get; set; } = { 8 };
            public void Run(SomaGenerationInputs inputs, SomaGenerationOutputs outputs)
            {
                if (PredGlobalMotions != null)
                {
                    Array.Copy(PredGlobalMotions, outputs.PredGlobalMotions, PredGlobalMotions.Length);
                }

                if (PredNumTokens != null)
                {
                    Array.Copy(PredNumTokens, outputs.PredNumTokens, PredNumTokens.Length);
                }
            }

            public void Dispose()
            {
            }
        }
    }
}

